    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleIncoming(intent);}
    private void deliverIncoming(){Intent intent=pendingIncoming;pendingIncoming=null;if(intent!=null)ui.post(()->handleIncoming(intent));}
    private void openScript(String id){work(tr("Открываю скрипт…"),()->{JSONObject script=Core.publicScript(api.request("GET","/scripts/"+id,null));ui.post(()->{if(alive())detailsSheet(script);});},null);}
    private void handleIncoming(Intent intent){
        if(intent==null)return;if(restoring){pendingIncoming=intent;return;}
        String action=intent.getStringExtra("library_action");if(action!=null){switch(action){case "search":screen=0;query="";render();ui.postDelayed(()->{if(search!=null){search.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);}},200);break;case "mine":screen=2;render();loadOwn();break;case "import":pickLua();break;case "favorites":favorites();break;case "recent":recentScripts();break;}return;}
        if(Intent.ACTION_SEND.equals(intent.getAction())){Uri file=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(file!=null){importLua(file,intent.getType());return;}}
        CharSequence shared=Intent.ACTION_PROCESS_TEXT.equals(intent.getAction())?intent.getCharSequenceExtra(Intent.EXTRA_PROCESS_TEXT):intent.getCharSequenceExtra(Intent.EXTRA_TEXT);
        String text=shared!=null?shared.toString():intent.getData()==null?"":intent.getData().toString();
        java.util.regex.Matcher room=java.util.regex.Pattern.compile("nullsbrawl://[^\\s<>\"']+",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text);if(room.find()){try{showBattleImport(BattleImport.parse(room.group()));}catch(Exception e){error(e);}return;}
        java.util.regex.Matcher url=java.util.regex.Pattern.compile("https://scripting\\.(?:nulls\\.gg|donutquine\\.dev)/(?:scripts/[0-9a-fA-F-]{36}|(?:users/)?@[A-Za-z0-9_.-]{1,64}|users/[0-9a-fA-F-]{36})(?=$|[\\s/?#<>\"'.,;!)}\\]])",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text);
        if(url.find()){Uri uri=Uri.parse(url.group());List<String> parts=uri.getPathSegments();if(parts.size()==2&&"scripts".equalsIgnoreCase(parts.get(0))){try{Core.requireUuid(parts.get(1));openScript(parts.get(1));}catch(Exception e){error(e);}return;}
            String handle=parts.size()==1?parts.get(0):parts.get(1);work(tr("Открываю автора…"),()->{JSONObject author=Core.publicUser(api.request("GET","/users/"+handle,null));JSONArray array=api.request("GET","/users/"+author.getString("uuid")+"/scripts",null).optJSONArray("scripts");List<JSONObject> authored=new ArrayList<>();if(array!=null)for(int i=0;i<array.length();i++)authored.add(Core.publicScript(array.getJSONObject(i)));ui.post(()->{if(alive())profile(author,authored);});},null);return;}
        String id=Core.scriptId(text);if(id!=null){openScript(id);return;}java.util.regex.Matcher uuid=java.util.regex.Pattern.compile("(?i)(?<![0-9a-z-])[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}(?![0-9a-z-])").matcher(text);if(uuid.find())openScript(uuid.group());
    }
