    private void importLua(Uri uri,String mime){
        if(!"content".equals(uri.getScheme())){error(new IllegalArgumentException(tr("Выберите файл .lua или .txt")));return;}
        work(tr("Читаю файл…"),()->{String name="script.lua";try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}if(name==null||name.isEmpty())name="script.lua";String lower=name.toLowerCase(Locale.ROOT);if(!lower.endsWith(".lua")&&!lower.endsWith(".lua.txt")&&!lower.endsWith(".txt")&&!(mime!=null&&mime.contains("lua")))throw new IllegalArgumentException(tr("Выберите файл .lua или .txt"));String source;try(InputStream stream=getContentResolver().openInputStream(uri)){source=Api.read(stream,5*1024*1024);}if(source.indexOf('\0')>=0)throw new IllegalArgumentException(tr("Выберите файл .lua или .txt"));String title=name.replaceFirst("(?i)(?:\\.lua)?\\.txt$|\\.lua$","");ui.post(()->{if(alive()){nextEditorName=title;editor(null,source);}});},null);
    }
