    private void filter(){if(screen!=0||adapter==null)return;rows.clear();for(JSONObject s:repo.scripts()){String handle=repo.handle(s.optString("author_uuid"));if(!blocklist.hidden(s,handle,sortMode)&&Core.matches(s,handle,query.isEmpty()||searchMode!=0&&searchMode!=4?null:repo.code(s.optString("uuid"))==null?null:sourceForUse(repo.code(s.optString("uuid"))),query,searchMode))rows.add(s);}rows.sort(Core.comparator(sortMode,seed));adapter.notifyDataSetChanged();}
