    private boolean canPublish(JSONObject script){String published=script.optString("published_at");if(published.isEmpty())return true;String id=script.optString("uuid");if(publishedWithoutFurtherEdit.contains(id))return false;if(editedSincePublish.contains(id))return true;String updated=script.optString("updated_at");try{return Instant.parse(updated).isAfter(Instant.parse(published));}catch(DateTimeParseException ignored){try{return OffsetDateTime.parse(updated).toInstant().isAfter(OffsetDateTime.parse(published).toInstant());}catch(DateTimeParseException ignoredAgain){return false;}}}
    private String date(String value){if(value==null||value.isEmpty())return tr("Без даты");try{Instant instant;boolean hasTime=value.contains("T")||value.contains(" ");try{instant=Instant.parse(value);}catch(DateTimeParseException e){try{instant=OffsetDateTime.parse(value).toInstant();}catch(DateTimeParseException e2){try{instant=LocalDateTime.parse(value.replace(' ','T')).atZone(ZoneId.systemDefault()).toInstant();}catch(DateTimeParseException e3){instant=LocalDate.parse(value.substring(0,10)).atStartOfDay(ZoneId.systemDefault()).toInstant();hasTime=false;}}}DateFormat format=hasTime?DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT,localizer.locale()):DateFormat.getDateInstance(DateFormat.MEDIUM,localizer.locale());return format.format(Date.from(instant));}catch(Exception e){return value.length()>=10?value.substring(0,10):value;}}
