    private void accountSettings(){
        if(!requireLogin())return;JSONObject identity=api.identity();String owner=identity.optString("uuid");LinearLayout c=column();
        LinearLayout profile=panel();profile.addView(text(identity.optString("name"),22,INK));profile.addView(label("@"+identity.optString("username")));addButton(profile,button("Null’s Connect",this::connectSettings));c.addView(profile);
        LinearLayout form=panel();form.addView(text(tr("Сменить пароль"),20,INK));boolean hasPassword=identity.optBoolean("has_password",true);
        EditText current=input(tr("Текущий пароль"),false),next=input(tr("Новый пароль"),false),repeat=input(tr("Повторите пароль"),false);
        for(EditText field:new EditText[]{current,next,repeat}){field.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);field.setFilters(new InputFilter[]{new InputFilter.LengthFilter(512)});}
        current.setAutofillHints(View.AUTOFILL_HINT_PASSWORD);next.setAutofillHints("newPassword");repeat.setAutofillHints("newPassword");
        if(hasPassword){form.addView(label(tr("Текущий пароль")));form.addView(current);}form.addView(label(tr("Новый пароль")));form.addView(next);form.addView(label(tr("Повторите пароль")));form.addView(repeat);
        Dialog dialog=sheet(tr("Настройки аккаунта"),c);Button save=primary(tr("Сохранить"),()->{});addButton(form,save);c.addView(form);
        save.setOnClickListener(v->{String old=current.getText().toString(),password=next.getText().toString();if(hasPassword&&old.isEmpty()){current.setError(tr("Введите имя и пароль"));return;}if(password.length()<8){next.setError(tr("Минимум 8 символов"));return;}if(!password.equals(repeat.getText().toString())){repeat.setError(tr("Пароли не совпадают"));return;}save.setEnabled(false);hideKeyboard();worker.execute(()->{try{api.changePassword(old,password,owner);ui.post(()->{if(!alive())return;current.setText("");next.setText("");repeat.setText("");dialog.dismiss();Toast.makeText(this,tr("Пароль изменён"),Toast.LENGTH_SHORT).show();});}catch(Exception error){ui.post(()->{save.setEnabled(true);error(error);});}});});
    }
    private void connectSettings(){
        if(!requireLogin())return;LinearLayout c=column();LinearLayout card=panel();c.addView(card);card.addView(text("Null’s Connect",22,INK));card.addView(label(tr(api.identity().optBoolean("has_connect_email")?"Подключено":"Не подключено")));Dialog dialog=sheet("Null’s Connect",c);
        if(!api.identity().optBoolean("has_connect_email"))addButton(card,primary(tr("Подключить"),()->{dialog.dismiss();connectAuthorize();}));addButton(card,button(tr("Обновить"),()->work(tr("Загрузка…"),()->api.refreshIdentity(),()->{dialog.dismiss();connectSettings();})));
    }
    private void connectAuthorize(){
        if(!requireLogin())return;final String owner=api.identity().optString("uuid");final boolean[] pending={false};
        WebView view=new WebView(this);view.setBackgroundColor(BG);view.getSettings().setJavaScriptEnabled(true);view.getSettings().setDomStorageEnabled(true);
        LinearLayout frame=column();frame.setBackgroundColor(BG);LinearLayout bar=row();bar.setPadding(dp(12),dp(8),dp(12),dp(8));bar.addView(text("Null’s Connect",20,INK),new LinearLayout.LayoutParams(0,-2,1));Dialog dialog=new Dialog(this);bar.addView(button(tr("Закрыть"),dialog::dismiss));frame.addView(bar);frame.addView(view,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(frame);
        view.setWebViewClient(new WebViewClient(){
            private boolean route(Uri uri){
                if("https".equalsIgnoreCase(uri.getScheme())&&"scripting.nulls.gg".equals(uri.getHost())&&"/connect".equals(uri.getPath())){
                    if(pending[0])return true;String token=uri.getQueryParameter("id_token");if(token==null&&uri.getFragment()!=null)token=Uri.parse("https://callback.invalid/?"+uri.getFragment()).getQueryParameter("id_token");
                    if(token==null||token.isEmpty()||token.length()>32768){Toast.makeText(MainActivity.this,tr("Не удалось выполнить"),Toast.LENGTH_SHORT).show();return true;}pending[0]=true;final String idToken=token;view.stopLoading();worker.execute(()->{try{api.connect(idToken,owner);ui.post(()->{if(!alive())return;dialog.dismiss();render();connectSettings();});}catch(Exception error){ui.post(()->{dialog.dismiss();error(error);});}});return true;
                }
                String host=uri.getHost();return !"https".equalsIgnoreCase(uri.getScheme())||host==null||!(host.equals("nulls.gg")||host.endsWith(".nulls.gg"));
            }
            @Override public boolean shouldOverrideUrlLoading(WebView web,WebResourceRequest request){return route(request.getUrl());}
            @Override public boolean shouldOverrideUrlLoading(WebView web,String url){return route(Uri.parse(url));}
        });dialog.setOnDismissListener(d->{view.stopLoading();view.destroy();});dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(-1,-1);
        String callback=Core.ORIGIN+"/connect?return_to=%2Fsettings";view.loadUrl(Uri.parse("https://connect.nulls.gg/authorize").buildUpon().appendQueryParameter("scope","openid email").appendQueryParameter("response_type","id_token").appendQueryParameter("redirect_uri",callback).appendQueryParameter("client_id","9").build().toString());
    }
    private void blacklistSheet(){
        LinearLayout c=column();Dialog[] current=new Dialog[1];Set<String> authors=blocklist.authors(),scripts=blocklist.scripts();
        c.addView(label(tr(api.authenticated()?"Синхронизируется с вашим аккаунтом.":"Сохраняется только на этом устройстве.")));
        if(authors.isEmpty()&&scripts.isEmpty())c.addView(label(tr("Чёрный список пуст")));
        if(!authors.isEmpty())c.addView(label(tr("Авторы")));
        for(String id:authors){JSONObject author=repo.author(id);c.addView(label(author==null?id:"@"+author.optString("username")));addButton(c,button(tr("Разблокировать"),()->{blocklist.unblockAuthor(id);current[0].dismiss();render();blacklistSheet();}));}
        if(!scripts.isEmpty())c.addView(label(tr("Скрипты")));
        for(String id:scripts){String name=id;for(JSONObject item:repo.scripts())if(id.equals(item.optString("uuid"))){name=item.optString("name",id);break;}c.addView(label(name));addButton(c,button(tr("Разблокировать"),()->{blocklist.unblockScript(id);current[0].dismiss();render();blacklistSheet();}));}
        current[0]=sheet(tr("Чёрный список"),c);
    }
