    private void website(String title,String url){android.webkit.CookieManager webCookies=android.webkit.CookieManager.getInstance();webCookies.setAcceptCookie(true);for(java.net.HttpCookie cookie:api.webCookies())webCookies.setCookie(Core.ORIGIN,cookie.getName()+"="+cookie.getValue());webCookies.flush();WebView view=new WebView(this);view.getSettings().setJavaScriptEnabled(true);view.getSettings().setDomStorageEnabled(true);view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView web,WebResourceRequest request){Uri uri=request.getUrl();String host=uri.getHost();if(host!=null&&(host.equals("scripting.nulls.gg")||host.equals("nulls.gg")||host.endsWith(".nulls.gg")))return false;open(uri.toString());return true;}});Dialog dialog=new Dialog(this);LinearLayout frame=column();frame.setBackgroundColor(BG);LinearLayout bar=row();bar.setPadding(dp(12),dp(8),dp(12),dp(8));bar.addView(text(title,18,INK),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button(tr("Закрыть"),dialog::dismiss));frame.addView(bar);frame.addView(view,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(frame);dialog.show();Window window=dialog.getWindow();if(window!=null)window.setLayout(-1,-1);dialog.setOnDismissListener(d->view.destroy());view.loadUrl(url);}
